// spec: specs/guides-videos.md (2.5–2.7) · кейс: .qa/tests/guides-videos/GUIDES-24.md
// seed: tests/seed.user.spec.ts (user, сессия ../auth/user.json; файл не перезаписывается) · прод, только чтение:
// не-GET обрываются (в т.ч. продление сессии), SW выключен. «התנתקות» в меню профиля не нажимается.
// Тикет #359741 «מה רצוי»: «להסתיר את המדריכים מכל המשתמשים… רק מנהל (admin)»; шаг 1 тикета — «או עם משתמש רגיל».
// Роль читается из GET rest/v1/app_user — проверки «ссылок нет» делаются после его ответа и отрисовки иконок вошедшего.
import { test, expect, Page } from '@playwright/test';
import {
  prepareReadOnly, LOAD, NAV, GUIDES_LINKS, dismissPopups, openMobileMenu, expectNoGuidesContent,
  linkTexts, expectNext, CALC, PUBLISH, FAQ,
} from './guides.helpers';

test.use({ storageState: '../auth/user.json', serviceWorkers: 'block' });

const appUser = (page: Page) =>
  page.waitForResponse((r) => r.request().method() === 'GET' && /\/rest\/v1\/app_user\?/.test(r.url()) && r.ok(), LOAD);

test.describe('Гайды скрыты — обычный пользователь (#359741)', () => {
  test('user: в шапке, меню профиля и футере нет ссылок на гайды #359741 @desktop @prod-safe', async ({ page, context }) => {
    await prepareReadOnly(context);
    await dismissPopups(page);
    const role = appUser(page);
    await page.goto('/');
    await role;
    const banner = page.getByRole('banner');
    await expect(banner.locator('a[href="/mybusinesses"]').first(), 'user вошёл: иконка «המודעות שלי» в шапке').toBeVisible(LOAD);
    await expect(banner.getByRole('link', { name: CALC, exact: true }), 'шапка отрисована').toBeVisible(LOAD);

    await expect(banner.locator(GUIDES_LINKS), 'в шапке нет ссылок на /guides').toHaveCount(0);
    await expect(banner.getByRole('link', { name: /מדריכ/ }), 'в шапке нет «מדריכים»').toHaveCount(0);
    expectNext(await linkTexts(banner), CALC, PUBLISH, 'шапка');

    const footer = page.getByRole('contentinfo');
    await expect(footer.getByRole('link', { name: FAQ, exact: true }), 'футер отрисован').toBeVisible(LOAD);
    await expect(footer.locator(GUIDES_LINKS), 'в футере нет ссылок на /guides').toHaveCount(0);
    expectNext(await linkTexts(footer), CALC, FAQ, 'футер');

    // Меню профиля (аватар): только открыть и прочитать пункты.
    await banner.locator('button[aria-haspopup="menu"]').click();
    const profile = page.getByRole('menu');
    await expect(profile.getByRole('menuitem', { name: 'פרופיל אישי' }), 'меню профиля открыто').toBeVisible(LOAD);
    await expect(profile.getByRole('menuitem', { name: /מדריכ/ }), 'в меню профиля нет гайдов').toHaveCount(0);
    await expect(profile.locator(GUIDES_LINKS), 'в меню профиля нет ссылок на /guides').toHaveCount(0);
    await page.keyboard.press('Escape');
    await expect(profile, 'меню профиля закрыто').toBeHidden();

    await expect(page.locator(GUIDES_LINKS), 'на всей странице нет ссылок на /guides').toHaveCount(0);
  });

  test('user: в мобильном меню «תפריט» нет «מדריכים», 4-й пункт — калькулятор, 5-й — «פרסום עסק למכירה» #359741 @mobile @prod-safe', async ({ page, context }) => {
    await prepareReadOnly(context);
    await dismissPopups(page);
    const role = appUser(page);
    await page.goto('/');
    await role;
    const menu = await openMobileMenu(page);
    await expect(menu.getByRole('link', { name: 'המודעות שלי', exact: true }), 'user вошёл: «המודעות שלי» в меню').toBeVisible(LOAD);
    await expect(menu.locator(GUIDES_LINKS), 'в меню нет ссылок на /guides').toHaveCount(0);
    await expect(menu.getByRole('link', { name: /מדריכ/ }), 'в меню нет «מדריכים»').toHaveCount(0);
    const items = menu.getByRole('link');
    await expect(items.nth(3), '4-й пункт').toHaveText(CALC);
    await expect(items.nth(4), '5-й пункт').toHaveText(PUBLISH);
  });

  for (const url of ['/guides', '/guides?x=1'] as const) {
    test(`user: прямой ${url} → главная без контента гайдов, «назад» не возвращает на /guides #359741 @desktop @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      await dismissPopups(page);
      await page.goto('/calculator');
      await expect(page.locator('#calc-purchasePrice'), '/calculator открыт').toBeVisible(LOAD);

      const role = appUser(page);
      await page.goto(url);
      await role;
      await page.waitForURL((u) => u.pathname === '/', NAV);
      await expect(page.getByRole('link', { name: 'צפה בכל העסקים' }).first(), 'главная отрисована').toBeVisible(LOAD);
      await expect(page.getByRole('banner').locator('a[href="/mybusinesses"]').first(), 'user остаётся вошедшим на главной').toBeVisible(LOAD);
      await expectNoGuidesContent(page, url);

      await page.goBack();
      await page.waitForURL((u) => u.pathname === '/calculator', NAV);
      await expect(page).not.toHaveURL(/guides/i);
    });
  }

  test('user: прямой /guides на телефоне → главная без контента гайдов #359741 @mobile @prod-safe', async ({ page, context }) => {
    await prepareReadOnly(context);
    await dismissPopups(page);
    const role = appUser(page);
    await page.goto('/guides');
    await role;
    await page.waitForURL((u) => u.pathname === '/', NAV);
    await expect(page.getByRole('link', { name: 'צפה בכל העסקים' }).first(), 'главная отрисована').toBeVisible(LOAD);
    await expectNoGuidesContent(page, '/guides (mobile)');
  });
});
